// Console — the page that hosts each network's RUN session (`the-console-hosts-one-run-session-per-network`),
// AS GRAPH SOURCE. A run session EXECUTES what its network has built for the user — it does not configure it
// and it does not build it — and when the network cannot do something yet it contracts the network's
// architect (`bsc session ask network-<slug>:architect`). One per network: the session is the network's
// steward, on `network-<slug>:steward`.
//
// LAZY AND REAPED. The console lists every network, starts a run session only when the user opens it, and
// hosts only that one terminal. Only the OPEN session is viewed, so the one the user moved away from — or
// every one, once the console is hidden — is reaped once it is quiet; a busy turn is never cut off. Whether
// a session is running is OBSERVED from the PTY host on each read, never stored, and reopening it continues
// its conversation because its directory is fixed.
//
// IT HOSTS NOTHING ELSE (`project-fleet-panes-live-only-in-glance`). A project's director, workers, triage and
// debug panes live only in Glance, and the tutors are no longer listed here.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { recordRender } from "@/shared/lib/core/perf";
import { useConsolePumps } from "@/app/console/useConsolePumps";
import { useDirectorPump } from "@/app/console/useDirectorPump";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Button } from "@/shared/ui/controls/Button";
import { Text } from "@/shared/ui/typography/Text";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { useScreenDescriptor } from "@/shared/hooks/useScreenDescriptor";
import { useRunSessionViewer } from "@/features/studio-sessions";
import { networkStewardPaneId, networkRootSession } from "@/shared/lib/session/systemSessions";
import { readPaneRuntimes, isPaneWorking, isPanePresent } from "@/shared/lib/session/paneRuntimeRead";

/** How often the console re-reads what the PTY host says about each run session while it is showing. */
const RUN_SESSION_STATUS_MS = 3000;

export function ConsoleWorkspace() {
  // App-wide pumps live in their own record now; mounted here because ConsoleWorkspace stays mounted
  // across every screen, so the fleet keeps advancing off-screen.
  useConsolePumps();

  const activeWorkspace   = useAppStore((s) => s.activeWorkspace);
  // Showing = the console is the active workspace. A hidden console must not keep a session it opened pinned
  // alive, or the reaper could never take it.
  const showing           = activeWorkspace === "console";

  useEffect(() => { recordRender(); });

  // The director pump is inert since #app-stops-pushing-prompts but is still called; it reads a live
  // pane-status ref. Kept until the record graph drops the call.
  const paneStatuses = useAppStore((s) => s.paneStatus);
  const paneStatusesRef = useRef(paneStatuses);
  useEffect(() => { paneStatusesRef.current = paneStatuses; }, [paneStatuses]);
  useDirectorPump(paneStatusesRef);

  // EVERY NETWORK, one run session each, in tab order — read from the network store the app hydrates at boot.
  const networks = useAppStore((s) => s.networks);

  // THE NETWORK WHOSE RUN SESSION THE USER OPENED. Opening it is the lazy start: the viewer makes it wanted, its
  // mount prepares its workspace, and its terminal launches. Local to this view — which one was open is
  // navigation, and nothing about a session's life depends on it.
  const [openId, setOpenId] = useState<string | null>(null);
  const open = networks.find((n) => n.id === openId) ?? null;
  useRunSessionViewer(open?.id ?? null, showing);

  // A slot only while the session is WANTED. A reaped session leaves the wanted list, and a slot left behind
  // would keep its dead terminal claimed, so the next open would reattach to nothing instead of launching.
  const openWanted = useAppStore((s) => (open ? s.wantedRunSessions.includes(open.id) : false));

  // WHAT EACH RUN SESSION IS DOING, READ FROM THE PTY HOST while the console is showing. A read that could not
  // run leaves the last answer in place rather than claiming every session stopped.
  const [status, setStatus] = useState<Record<string, "stopped" | "running" | "working">>({});
  const networkIds = networks.map((n) => n.id).join(" ");
  useEffect(() => {
    if (!showing) return;
    const ids = networkIds ? networkIds.split(" ") : [];
    let alive = true;
    const read = async () => {
      const runtimes = await readPaneRuntimes(ids.map(networkStewardPaneId));
      if (!alive || runtimes === null) return;
      setStatus(Object.fromEntries(ids.map((id) => {
        const view = runtimes.get(networkStewardPaneId(id));
        return [id, isPaneWorking(view) ? "working" : isPanePresent(view) ? "running" : "stopped"];
      })));
    };
    void read();
    const timer = setInterval(() => { void read(); }, RUN_SESSION_STATUS_MS);
    return () => { alive = false; clearInterval(timer); };
  }, [showing, networkIds]);

  // WHAT `bsc app go` CAN SELECT HERE (`the-shared-navigation-mechanism-drill-select-and-show`): each network's
  // run session, addressed by its PANE id.
  useScreenDescriptor({
    workspace: "console",
    layer: "sessions",
    drill: [],
    selection: open ? networkStewardPaneId(open.id) : null,
    targets: networks.map((n) => ({ id: networkStewardPaneId(n.id), label: n.name, drillable: false, selectable: true })),
    select: (id) => {
      const root = networkRootSession(id);
      if (root?.kind === "steward" && networks.some((n) => n.id === root.networkId)) setOpenId(root.networkId);
    },
  });

  return (
    <Stack style={{ flex: 1, minHeight: 0, background: "var(--bg-canvas)" }} data-testid="console-run-sessions">
      <Row wrap style={{ gap: 8, padding: 8 }}>
        {networks.map((n) => (
          <Button
            key={n.id}
            variant={open?.id === n.id ? "primary" : "default"}
            aria-pressed={open?.id === n.id}
            data-testid={`run-session-${n.id}`}
            title={`the ${n.name} network's run session — executes what it has built, and asks its architect for what it has not`}
            onClick={() => setOpenId(n.id)}
          >
            {n.name} · {status[n.id] ?? "stopped"}
          </Button>
        ))}
      </Row>
      {open && openWanted ? (
        <Stack style={{ flex: 1, minHeight: 0 }}>
          <TerminalSlot paneId={networkStewardPaneId(open.id)} visible={showing} focused={showing} />
        </Stack>
      ) : (
        <Text style={{ padding: 16 }}>
          {networks.length === 0
            ? "No networks yet. Create one in Glance and its run session appears here."
            : "Open a network to start its run session. It executes what the network has built, and asks the network's architect for anything it cannot do yet. Nothing runs until you open it, a session you move away from is reaped once it is quiet, and opening it again continues its conversation."}
        </Text>
      )}
    </Stack>
  );
}

